pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the amount and the caller
    function testFuzz_property(uint256 rawAmount, address actor) public {
        // keep actor non-zero
        vm.assume(actor != address(0));

        // bound the amount to a wide range but include 10 ether as possible
        uint256 amount = bound(rawAmount, 0, type(uint256).max);

        // We need to observe the behavior when block.number % 15 == 0, so warp to such a block.
        // Keep it broad: advance to some future block that satisfies the condition.
        uint256 target = block.number;
        // find next block with mod 15 == 0
        while (target % 15 != 0) { target++; }
        // warp to that block's timestamp and set roll to that block number
        // Note: vm.roll and vm.warp are allowed. Use roll to set block number.
        vm.roll(target);

        // Fund the contract with 1 ether so there's a balance to transfer if accepted
        vm.deal(address(this), 1 ether);
        // send 1 ether into c from this contract
        (bool s,) = address(c).call{value: 1 ether}("");
        require(s, "funding failed");

        // Ensure actor has enough balance to send `amount` in the fuzzed call
        uint256 supply = amount + 1 ether;
        if (supply < amount) supply = amount; // overflow guard (practically impossible)
        vm.deal(actor, supply);

        // make the call from actor with the fuzzed amount and record whether it succeeded
        bool ok;
        vm.startPrank(actor);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The general rule we assert: For the correct contract C, when we call fallback at a block where block.number % 15 == 0,
        // if the call is accepted (does not revert) and msg.value == 10 ether, then the contract should have forwarded its entire balance to the caller,
        // leaving address(c).balance == 0. Conversely, if msg.value != 10 ether (and call accepted), the contract keeps its balance.
        // Instead of branching, we assert the universal fact that whenever the call succeeded and amount == 10 ether,
        // the contract balance is zero (the transfer happened). This is true for the reference and false for the mutant (which rejects amount==10 ether).

        // We only assert when the call succeeded and amount == 10 ether.
        if (amount == 10 ether && ok) {
            // exactly one assertion reading c's public surface: the contract balance must be zero
            assertTrue(address(c).balance == 0);
        } else {
            // If amount != 10 ether or call reverted, we assert the universal property holds vacuously by asserting true on a fact about C:
            // if the call succeeded and amount != 10 ether, the reference keeps the balance so address(c).balance == 1 ether
            // But to keep a single assertTrue per run and remain a universal property across admissible inputs,
            // we assert that either the call succeeded implies that (amount == 10 ether) == (address(c).balance == 0).
            // To keep a single assertTrue always executed, we evaluate the equivalence.
            bool left = ok;
            bool right = (address(c).balance == 0);
            // For the reference, left iff (amount == 10 ether and transfer executed) which makes left == right.
            // For the mutant, there will be inputs where this equivalence fails (e.g., amount == 10 ether but call reverted -> left=false right=true),
            // causing the test to fail.
            assertTrue(left == (amount == 10 ether && right));
        }
    }
}

