        uint256 b = bound(targetBlockNumber, block.number, block.number + 1000);

        // Ensure the call value is exactly 10 ether as required by the contract
        uint256 callValue = 10 ether;

        // Fund the actor so the low-level call can send 10 ether
        vm.deal(actor, callValue);

        // Advance to target block
        vm.roll(b);

        // Ensure timestamp strictly increases relative to pastBlockTime (initial 0), so any positive timestamp is OK
        // Warp to a nonzero timestamp (must be > 0). Use block.timestamp + 1 to ensure strict increase.
        vm.warp(block.timestamp + 1);

        // Make the call as the actor sending exactly 10 ether to fallback
        vm.prank(actor);
        // perform the external payable fallback call via low-level call to ensure fallback is invoked
        (bool ok, ) = address(c).call{value: callValue}("");
        // The reference requires msg.value == 10 ether and timestamp > pastBlockTime, so call should succeed
        // For both reference and mutant the call will succeed under admissible inputs; what differs is whether
        // the contract transfers out its balance depending on block.number % 15 vs % 16.
        // We now assert a universal property about the reference: after this call, if block.number % 15 != 0
        // then the contract's balance remains equal to the 10 ether sent (i.e., it did not transfer the funds away).

        // Single assertion: reference contract never drains its balance on a non-15-divisible block.
        // We observe c only via address(c).balance. This is a universal property the reference satisfies
