pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: caller address and an arbitrary timestamp and block number offset.
    // We fuzz an address (as caller) and uint256 t to derive a future block timestamp/number such that
    // the admissible scenario (msg.value == 10 ether and block.timestamp > pastBlockTime) holds.
    function testFuzz_property(address caller, uint256 t) public {
        // keep caller non-zero
        vm.assume(caller != address(0));

        // start with funding the contract so it has some balance to possibly forward
        vm.deal(address(this), 100 ether);
        // send some ether into c from this test contract
        payable(address(c)).transfer(50 ether);

        // Ensure we call fallback with exactly 10 ether from the fuzzed caller
        vm.deal(caller, 10 ether);

        // Make sure timestamp advances beyond pastBlockTime stored in c: read the getter
        uint256 prevTime = c.pastBlockTime();
        // choose a warp time strictly greater than prevTime; use fuzzed t but ensure it's greater
        uint256 warpTo = prevTime + 1 + (t % 1000);
        vm.warp(warpTo);

        // Also set block.number so that we can make it divisible by 15 for some fuzzed t values.
        // We'll compute a block number that is divisible by 15 using the fuzzed t to vary it.
        uint256 base = block.number;
        uint256 desired = base + (uint256(15) - (base % 15)) % 15 + (t % 30);
        // warp block number by rolling
        vm.roll(desired);

        // Now call fallback from the fuzzed caller sending exactly 10 ether.
